import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import './Alternatives.css';
import { jsPDF } from 'jspdf';
import html2canvas from 'html2canvas';
import QRious from 'qrious';
import { IS_LOCAL } from '../../config';
import { fetchAPI } from '../../utils/api';

const fetchHaywardProduct = async (sku) => {
  try {
    const response = await fetch(
      `https://hayward.com/rest/default/V1/products/${sku}`,
      {
        headers: {
          Authorization: "Bearer 3b5kg5eu34t3gdmkiph3m1aqcgun8cu6",
        },
      }
    );
    if (!response.ok) {
      throw new Error('Network response was not ok');
    }
    const result = await response.json();
    return result;
  } catch (error) {
    console.error("Fetch error: ", error);
    throw error;
  }
};

const truncateDescription = (description, maxLength) => {
  if (description.length <= maxLength) return description;
  return description.slice(0, maxLength) + '...';
};

const Alternatives = ({ onRestart }) => {
  const { search } = useLocation();
  const params = new URLSearchParams(search);
  const modelId = params.get('model');
  const navigate = useNavigate();

  const [model, setModel] = useState(null);
  const [relatedModels, setRelatedModels] = useState([]);
  const [category, setCategory] = useState(null);
  const [manufacturer, setManufacturer] = useState(null);
  const [series, setSeries] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);

        // Fetch all required data
        const [categoriesResponse, manufacturersResponse, seriesResponse, modelsResponse] = await Promise.all([
          fetchAPI('categories'),
          fetchAPI('manufacturers'),
          fetchAPI('series'),
          fetchAPI('models'),
        ]);

        if (!categoriesResponse.ok || !manufacturersResponse.ok || !seriesResponse.ok || !modelsResponse.ok) {
          throw new Error('Failed to fetch required data');
        }

        const [categoriesData, manufacturersData, seriesData, modelsData] = await Promise.all([
          categoriesResponse.json(),
          manufacturersResponse.json(),
          seriesResponse.json(),
          modelsResponse.json(),
        ]);

        // Find the selected model
        const selectedModel = modelsData.models.find((m) => m.id === parseInt(modelId));
        if (!selectedModel) {
          throw new Error('Model not found');
        }
        setModel(selectedModel);

        // Find category, manufacturer, and series
        setCategory(categoriesData.categories.find((cat) => parseInt(cat.id) === parseInt(selectedModel.categoryId)));
        setManufacturer(manufacturersData.manufacturers.find((man) => parseInt(man.id) === parseInt(selectedModel.manufacturerId)));
        setSeries(seriesData.series.find((ser) => parseInt(ser.id) === parseInt(selectedModel.seriesId)));

        // Fetch related models
        const relatedResults = await Promise.all(
          ['best', 'better', 'good'].map(async (key) => {
            const sku = selectedModel.relatedModels[key];
            if (sku) {
              try {
                if (IS_LOCAL) {
                  // Mock data fallback
                  throw new Error('Mock data mode not implemented'); // Adjust this as needed
                } else {
                  const result = await fetchHaywardProduct(sku.trim());
                  return { key, result };
                }
              } catch (err) {
                return { key, error: err.message };
              }
            }
            return null;
          })
        );

        setRelatedModels(relatedResults.filter((res) => res !== null));
      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [modelId]);

  const createPdfStructure = async () => {
    const pdf = new jsPDF('p', 'mm', 'a4');
    const content = document.getElementById('pdf-content');

    pdf.setFontSize(18);
    pdf.text('Hayward Best-in-Class Options', 10, 20);

    const canvas = await html2canvas(content, {
      ignoreElements: (element) => element.classList.contains('no-print'),
    });
    const imgData = canvas.toDataURL('image/png');
    const pdfWidth = pdf.internal.pageSize.getWidth();
    const pdfHeight = (imgData.height * pdfWidth) / imgData.width;

    pdf.addImage(imgData, 'PNG', 0, 30, pdfWidth, pdfHeight);

    const qr = new QRious({
      value: window.location.href,
      size: 100,
    });
    const qrImage = qr.toDataURL('image/jpeg');

    pdf.addImage(qrImage, 'JPEG', pdf.internal.pageSize.getWidth() - 40, pdf.internal.pageSize.getHeight() - 40, 30, 30);

    pdf.save('hayward-alternatives.pdf');
  };

  if (loading) {
    return <div>Loading...</div>;
  }

  if (error) {
    return <div>Error: {error}</div>;
  }

  return (
    <div className="alternatives-container">
      <h2 className="title mt-3 mb-5">Our Best-in-Class Options</h2>
      <div id="pdf-content">
        <div className="flex-container">
          {relatedModels.map(({ key, result, error }, index) => {
            if (error) {
              return (
                <div key={index} className={`col-12 col-md-3 model-card ${key}`}>
                  <h3>{key.charAt(0).toUpperCase() + key.slice(1)}</h3>
                  <p>{error}</p>
                </div>
              );
            }

            const descriptionAttribute = result.custom_attributes.find((attr) => attr.attribute_code === 'marketing_short_description');
            const description = descriptionAttribute ? descriptionAttribute.value : 'No description available';
            const truncatedDescription = truncateDescription(description, 150);

            return (
              <div key={index} className={`col-12 col-md-3 model-card ${key}`}>
                <h3>{key.charAt(0).toUpperCase() + key.slice(1)}</h3>
                <img src={`/media/catalog/product/${result.media_gallery_entries[0]?.file}`} alt={result.name} />
                <h4>{result.name}</h4>
                <p>SKU: {result.sku}</p>
                <p>{truncatedDescription}</p>
                <a href="#" target="_blank" rel="noopener noreferrer">
                  View Details
                </a>
              </div>
            );
          })}
        </div>
      </div>
      <button onClick={createPdfStructure}>Download PDF</button>
    </div>
  );
};

export default Alternatives;
